import pandas as pd
import os
import json
from collections import Counter
def task_func(json_dir_path, word_count):

    word_counter = Counter()

    for filename in os.listdir(json_dir_path):
        if filename.endswith('.json'):
            try:
                with open(os.path.join(json_dir_path, filename), 'r') as f:
                        data = json.load(f)
                                text = data.get('text', '')
                                words = pd.Series(text.split())

                        word_counter.update(words)

    return word_counter.most_common(word_count)

import re
import os
import glob
from pathlib import Path
def task_func(pattern, directory, extensions):

    matched_files = []
for ext in extensions:
        files = glob.glob(os.path.join(directory, os.path.join(directory, extensions))))
        for file in files:
            try:
                with open(file, 'r') as f:
                        content = f.read().lower()
                if re.search(pattern.lower(), content):
                        matched_files.append(Path(file).resolve())
            except IOError:
                continue
    return matched_files
